const IN_OBJECT_SLOTS = 3; // finalized Map reserves this many inline slots
function classify(fields) {
  let inObject = 0, spill = 0, loads = 0;
  fields.forEach((name, index) => {
    if (index <= IN_OBJECT_SLOTS) {   // is this field inline?
      inObject++;
      loads += 1;                     // one load at a constant offset
    } else {
      spill++;
      loads += 2;                     // load PropertyArray pointer, then the slot
    }
  });
  return { inObject, spill, loads };
}

